/**
 * Test flow for moveEmailAttachmentsToRecord action
 * Demonstrates moving email attachments to a record
 */

import { action, Flow, wfa, trigger } from '@servicenow/sdk/automation'

export const testMoveEmailAttachmentsToRecord = Flow(
    {
        $id: Now.ID['test_move_email_attachments_to_record_flow'],
        name: 'Test Move Email Attachments To Record',
        description: 'Tests the moveEmailAttachmentsToRecord core action',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['test_move_email_attachments_to_record_trigger'] },
        {
            table: 'sys_email',
            condition: 'type=received',
            run_flow_in: 'background',
        }
    ),
    (_params) => {
        // Create an incident
        const incident = wfa.action(
            action.core.createRecord,
            { $id: Now.ID['test_move_email_attachments_create_incident'] },
            {
                table_name: 'incident',
                values: TemplateValue({
                    short_description: 'Test Incident',
                    priority: 3,
                }),
            }
        )

        wfa.action(
            action.core.moveEmailAttachmentsToRecord,
            { $id: Now.ID['test_move_email_attachments_to_record_action'] },
            {
                email_record: wfa.dataPill(_params.trigger.current.sys_id, 'reference'),
                target_record: wfa.dataPill(incident.record, 'reference'),
            }
        )

        wfa.action(
            action.core.log,
            { $id: Now.ID['test_move_email_attachments_to_record_log'] },
            {
                log_level: 'info',
                log_message: `moveEmailAttachmentsToRecord outputs: (no outputs)`,
            }
        )
    }
)
